-- 6. Keyword-only baseline (inverted index, no vector): ordered by popularity
SELECT product_id, product_name, rating_number
FROM products
WHERE product_name MATCH_ALL 'insulated travel mug'
ORDER BY rating_number DESC
LIMIT 10;

-- 7. Facets for building your own WHERE clauses
SELECT product_type, count(*) AS n FROM products GROUP BY product_type ORDER BY n DESC LIMIT 15;
SELECT element_at(categories, 2) AS category, count(*) AS n FROM products
WHERE array_size(categories) >= 2 GROUP BY category ORDER BY n DESC LIMIT 15;
SELECT brand, count(*) AS n FROM products GROUP BY brand ORDER BY n DESC LIMIT 15;
